#include "City.h"
#include <algorithm>
#include <cmath>
#include <iostream>
#include <limits>
#include <stdexcept>
using namespace yoru;
namespace {
int checks=0;
void expect(bool value,const std::string& message){checks++;if(!value)throw std::runtime_error(message);}
bool near(double a,double b){return std::abs(a-b)<1e-5;}
Building& b(City& c,Position p){return *c.state.tiles.at(p).building;}
void put(City& c,Position p,Kind k){Building v;v.kind=k;v.stock=commissioningStock(k);c.state.tiles[p].building=v;}
City fixture(){City c;c.reset(true);put(c,{0,0},Kind::Exchange);for(int x=0;x<=8;x++){auto& t=c.state.tiles[{x,1}];t.road=t.power=t.water=true;}put(c,{1,0},Kind::Reactor);put(c,{2,0},Kind::Waterworks);put(c,{3,0},Kind::Clinic);put(c,{4,0},Kind::Arcade);put(c,{5,0},Kind::Market);put(c,{6,0},Kind::Office);c.buildCore({3,1,1});for(int x=2;x<=6;x++){auto& t=c.state.tiles[{x,1,1}];t.deck=t.walk=t.power=t.water=true;}c.buildDeck({3,0,1});put(c,{3,0,1},Kind::Capsule);b(c,{3,0,1}).residents=32;c.connect({2,1,0},{2,1,1},ConnectorKind::Riser);c.connect({3,1,0},{3,1,1},ConnectorKind::Stairs);c.evaluate();return c;}
void invariant(City& c){auto state=serialize(c.state);auto forecast=c.totals;for(int i=0;i<3;i++)c.evaluate();expect(serialize(c.state)==state,"Forecasts preserve health, condition, queue memory and stores");expect(near(forecast.waterDelivered,c.totals.waterDelivered),"Water forecasts are deterministic");for(auto& e:c.edges)expect(e.load<=e.capacity+1e-6&&e.load>=-1e-6,"All travel and utility channels respect shared edge capacity");expect(c.totals.waterDelivered+c.totals.waterCharging<=c.totals.waterSupply+1e-6,"Boosting never creates water");expect(c.totals.powerDelivered+c.totals.powerCharging<=c.totals.powerSupply+1e-6,"Lift and booster power never creates electricity");double work=0;for(auto& [p,t]:c.state.tiles)if(t.building){auto& home=*t.building;expect(home.employedResidents<=home.residents*.62+1e-6,"Worker profiles cannot double-book residents");work+=home.employedResidents;}expect(near(work,c.totals.pedestrianTrips),"Workers balance across both mobility profiles");}
}
int main(){try{
    auto c=fixture();auto home=Position{3,0,1};expect(b(c,home).walk&&!b(c,home).stepFree,"Stairs provide general access but no step-free entrance");expect(near(b(c,home).assistedEmployed,0),"Step-free workers cannot use stairs");expect(b(c,home).care>0&&b(c,home).care<=.820001,"Stair-only care is limited to the general mobility profile");expect(b(c,home).leisure>0&&b(c,home).leisure<=.820001,"Leisure is a routed visit, not a planar radius");
    for(auto& j:c.journeys)if(j.from==home)expect(!j.stepFree,"No assisted journey crosses the stair-only flight");
    c.connect({6,1,0},{6,1,1},ConnectorKind::Lift);size_t lift=c.state.connectors.size()-1;c.evaluate();expect(b(c,home).stepFree&&b(c,home).assistedEmployed>0,"A powered lift opens real step-free work journeys");expect(b(c,home).care>.99&&b(c,home).leisure>.99,"Accessible clinic and leisure capacity serves all profiles");
    double care=0,leisure=0;for(auto& j:c.journeys){if(j.purpose==JourneyPurpose::Care)care+=j.people;if(j.purpose==JourneyPurpose::Leisure)leisure+=j.people;if(j.stepFree)for(size_t i=1;i<j.path.size();i++)for(auto& link:c.state.connectors)if((j.path[i-1]==link.a&&j.path[i]==link.b)||(j.path[i-1]==link.b&&j.path[i]==link.a))expect(link.kind!=ConnectorKind::Stairs,"Every assisted path excludes stairs");}expect(care>0&&leisure>0&&near(care+leisure,c.totals.serviceTrips),"Distinct service journeys balance visit totals");
    c.toggle({1,0});expect(!b(c,home).stepFree&&near(c.state.connectors[lift].power,0),"Power loss removes step-free shaft access immediately");c.toggle({1,0});
    c.state.connectors[lift].condition=.1;c.evaluate();expect(!b(c,home).stepFree,"A worn-out transfer closes safely");c.beginEdit();auto worn=serialize(c.state);expect(c.serviceConnector(lift)&&b(c,home).stepFree,"An overhaul restores transfer service");c.undo();expect(serialize(c.state)==worn,"Overhaul undo preserves all persistent state");c.serviceConnector(lift);
    c.beginEdit();double motor=c.state.connectors[lift].power;expect(c.upgradeConnector(lift),"Transfer capacity can be upgraded");expect(c.state.connectors[lift].tier==2&&c.state.connectors[lift].power>=motor-.01,"Larger transfers draw their tiered power from the grid");c.undo();
    invariant(c);double health=b(c,home).health,condition=c.state.connectors[lift].condition;c.step();expect(b(c,home).health>=health&&b(c,home).health-health<.001,"Health improves gradually under good local service");expect(c.state.connectors[lift].condition<condition,"Used transfer machinery wears only on ticks");expect(c.state.connectors[lift].crowding>0,"Transfer queues remember real load");invariant(c);
    c.state.connectors[lift].crowding=1;c.evaluate();expect(c.state.connectors[lift].wait>=4,"Saturated transfers add a real travel cost");
    c.toggle({3,0});expect(near(b(c,home).care,0),"A closed clinic supplies no appointments");
    auto small=fixture();b(small,{3,0,1}).residents=32;small.state.tiles[{3,0}].building->condition=.13;small.evaluate();double appointments=0;for(auto& j:small.journeys)if(j.purpose==JourneyPurpose::Care)appointments+=j.people;expect(appointments<=12*b(small,{3,0}).productivity+1e-5,"Appointments cannot exceed actual provider productivity");
    City load;load.reset(true);load.buildCore({0,0,5});for(int z=1;z<=5;z++){load.buildDeck({1,0,z});put(load,{1,0,z},Kind::Reservoir);b(load,{1,0,z}).level=3;}load.evaluate();auto foundation=load.bearing[{0,0,0}];expect(foundation.load>load.bearing[{0,0,4}].load,"Foundations carry cumulative weight from the floors above");expect(foundation.ratio>1&&load.totals.stressedStructures>0,"Stacked heavy processes overload a real bearing path");expect(!b(load,{1,0,1}).supported,"Extreme bearing overload closes dependent decks");expect(load.strengthenCore({0,0,3}),"A core upgrade includes its foundation");expect(load.bearing[{0,0,0}].capacity==480,"The foundation receives the same reinforcement tier");load.strengthenCore({0,0,3});for(int z=1;z<=5;z++)load.reinforce({1,0,z});expect(load.bearing[{0,0,0}].ratio<1&&b(load,{1,0,1}).supported,"Reinforcing the complete path clears the safety closure");
    auto before=serialize(load.state);load.evaluate();expect(serialize(load.state)==before,"Bearing analysis never moves or destroys authored structures");load.state.tiles[{0,0,0}].structuralCondition=.05;load.evaluate();expect(!b(load,{1,0,1}).supported,"A failed foundation interrupts support at every dependent level");load.serviceStructure({0,0,0});expect(b(load,{1,0,1}).supported,"Foundation repair restores the stack");
    City water;water.reset(true);put(water,{0,0},Kind::Exchange);put(water,{1,0},Kind::Reactor);put(water,{2,0},Kind::Waterworks);for(int x=0;x<=4;x++){auto& t=water.state.tiles[{x,1}];t.road=t.power=t.water=true;}water.connect({4,1,0},{4,1,7},ConnectorKind::Riser);water.connect({3,1,0},{3,1,7},ConnectorKind::Lift);for(int z:{3,6,7}){water.buildCore({2,1,z});for(int x=2;x<=4;x++){auto& t=water.state.tiles[{x,1,z}];t.deck=t.power=t.water=t.walk=true;}water.buildDeck({2,0,z});}put(water,{2,0,7},Kind::Capsule);water.evaluate();expect(near(b(water,{2,0,7}).water,0),"A connected pipe cannot deliver above its source head");put(water,{2,0,3},Kind::Booster);water.evaluate();expect(near(b(water,{2,0,7}).water,0),"One booster has a finite delivery elevation");put(water,{2,0,6},Kind::Booster);water.evaluate();expect(b(water,{2,0,7}).water>.99&&b(water,{2,0,7}).head>=7,"Cascaded powered boosters transfer actual water to higher strata");expect(water.totals.waterBoosted>0,"Boosted throughput is reported separately from source supply");invariant(water);water.toggle({2,0});expect(near(b(water,{2,0,7}).water,0)&&near(water.totals.waterBoosted,0),"Pumps without an inlet cannot invent water");water.toggle({2,0});water.toggle({1,0});expect(near(water.totals.waterBoosted,0),"A water booster needs electricity");
    auto crews=fixture();put(crews,{7,0},Kind::Maintenance);crews.state.connectors[1].condition=.5;b(crews,{6,0}).condition=.5;crews.state.tiles[{3,1,0}].structuralCondition=.5;crews.evaluate();
    double allocated=0;for(auto& [p,t]:crews.state.tiles)if(t.building)allocated+=t.building->maintenance;for(auto& link:crews.state.connectors)allocated+=link.maintenance;for(auto& [p,member]:crews.bearing)allocated+=member.repair;
    expect(crews.state.connectors[1].maintenance>0&&crews.bearing[{3,1,0}].repair>0,"A parts-fed workshop can reach both transfer machinery and foundations");expect(allocated<=.08*b(crews,{7,0}).productivity+1e-6,"Buildings, connectors and structure share one finite repair budget");double transferBefore=crews.state.connectors[1].condition;crews.step();expect(crews.state.connectors[1].condition>transferBefore,"Workshop repair commits to actual transfer condition");
    City hump;hump.reset(true);put(hump,{1,0},Kind::Reactor);put(hump,{2,0},Kind::Waterworks);for(int x=1;x<=4;x++){auto& t=hump.state.tiles[{x,1}];t.power=t.water=true;}hump.connect({4,1,0},{4,1,4},ConnectorKind::Riser);hump.buildCore({6,1,4});for(int x=4;x<=7;x++){auto& t=hump.state.tiles[{x,1,4}];t.deck=t.water=t.power=true;}hump.connect({7,1,1},{7,1,4},ConnectorKind::Riser);hump.buildDeck({7,0,1});put(hump,{7,0,1},Kind::Capsule);hump.evaluate();expect(near(b(hump,{7,0,1}).water,0),"Water cannot cross an over-head hump merely because its destination is lower");
    auto saved=serialize(c.state);expect(serialize(deserialize(saved))==saved,"Schema four round-trips health, structure, transfer tiers, wear and queue memory");for(int i=0;i<6;i++){auto bad=saved;if(i==0)bad["connectors"][0]["tier"]=4;if(i==1)bad["connectors"][0]["crowding"]=-1;if(i==2)bad["connectors"][0]["condition"]=2;if(i==3)bad["tiles"][0]["structuralCondition"]=-1;if(i==4)bad["tiles"][0]["structureLevel"]=0;if(i==5)for(auto& t:bad["tiles"])if(t.contains("building")){t["building"]["health"]=2;break;}bool rejected=false;try{deserialize(bad);}catch(...){rejected=true;}expect(rejected,"Invalid persistent ecology state is rejected atomically");}
    auto legacy=saved;legacy["version"]=3;for(auto& t:legacy["tiles"]){t.erase("structuralCondition");t.erase("structureLevel");t.erase("walkLevel");if(t.contains("building"))t["building"].erase("health");}for(auto& link:legacy["connectors"])for(auto key:{"tier","condition","crowding","priority"})link.erase(key);auto migrated=deserialize(legacy);expect(migrated.tiles.size()==c.state.tiles.size()&&migrated.connectors.size()==c.state.connectors.size(),"V3 migration preserves every authored position and transfer");expect(migrated.connectors[0].tier==1&&migrated.connectors[0].condition==1,"Old connections receive conservative valid defaults");
    City demo;demo.reset();for(int tick=0;tick<50;tick++){invariant(demo);demo.step();}expect(demo.totals.population>1000,"Starter city remains viable with social and engineering constraints");
    std::cout<<"PASS "<<checks<<" urban ecology, access, bearing and pressure checks\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}}
